                                      int OH, int OW) {
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long total = (long)N * OC * OH * OW;
    if (idx >= total) return;
    int ow = idx % OW;
    long tmp = idx / OW;
    int oh = tmp % OH;
    tmp /= OH;
    int oc = tmp % OC;
    int n  = tmp / OC;
    T acc = (T)0;
    if (b != nullptr) {
        acc = b[oc];
    }
    for (int c = 0; c < C; ++c) {
        for (int kh = 0; kh < KH; ++kh) {
            int ih = oh * stride_h - pad_h + kh;
            if (ih < 0 || ih >= H) continue;
            for (int kw = 0; kw < KW; ++kw) {
                int iw = ow * stride_w - pad_w + kw;
